-- Depois (3NF)
CREATE TABLE cep (
  cep    CHAR(8) PRIMARY KEY,
  cidade VARCHAR(100) NOT NULL
);
CREATE TABLE usuario (
  id   SERIAL PRIMARY KEY,
  nome VARCHAR(100) NOT NULL,
  cep  CHAR(8) REFERENCES cep(cep)
);

