-- BASE (consistência eventual): a escrita vai para o nó A;
-- uma leitura logo depois no nó B pode ainda ver o valor antigo
-- até a replicação terminar.

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Usuario {
  @Id
  private Long id;
  private String nome;

  protected Usuario() {} // JPA exige construtor sem argumentos
  public Usuario(Long id, String nome) { this.id = id; this.nome = nome; }

  public Long getId() { return id; }
  public String getNome() { return nome; }
}
// Exemplo de uso
EntityManager em = ...;
em.persist(new Usuario(1L, "João"));

